// Core tests: the 7 literal core cases from fixtures.json (expected values
// taken verbatim from the file, never generated by the product), plus
// hand-derived boundary, validation, and property cases from the SPEC's
// tests section. Every expected value below was computed by hand from the
// SPEC's rules.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatMoney,
  formatPercentBp,
  formatZheDisplay,
  run,
} from "../public/js/core/discount.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  price: "100",
  discount1: "0",
  discount2: "0",
  coupon: "0",
  taxRate: "0",
  quantity: "1",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("price 0 and 0.00 are RANGE; 0.01 is the smallest valid price", () => {
  assert.deepEqual(errorOf({ ...base, price: "0" }), { code: "RANGE", field: "price", row: null });
  assert.deepEqual(errorOf({ ...base, price: "0.00" }), { code: "RANGE", field: "price", row: null });
  const outcome = run({ ...base, price: "0.01" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.steps[0].priceCents, 1);
  assert.equal(outcome.result.unitFinalCents, 1);
});

test("a money value with 8 integer digits is MONEY_FORMAT, not RANGE", () => {
  assert.deepEqual(errorOf({ ...base, price: "10000000" }), {
    code: "MONEY_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, price: "01" }), {
    code: "MONEY_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, price: "1.005" }), {
    code: "MONEY_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, price: " 100" }), {
    code: "MONEY_FORMAT",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, price: "１００" }), {
    code: "MONEY_FORMAT",
    field: "price",
    row: null,
  });
});

test("raw length is checked before grammar: a 13-unit price is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, price: "9999999.99999" }), {
    code: "INPUT_LIMIT",
    field: "price",
    row: null,
  });
});

test("an empty field is EMPTY; a lone surrogate is UNICODE", () => {
  assert.deepEqual(errorOf({ ...base, price: "" }), { code: "EMPTY", field: "price", row: null });
  assert.deepEqual(errorOf({ ...base, coupon: "\uD800" }), {
    code: "UNICODE",
    field: "coupon",
    row: null,
  });
});

test("percent grammar and the basis-point range", () => {
  assert.deepEqual(errorOf({ ...base, discount1: "1000" }), {
    code: "PERCENT_FORMAT",
    field: "discount1",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, discount2: "10.005" }), {
    code: "PERCENT_FORMAT",
    field: "discount2",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, taxRate: "-5" }), {
    code: "PERCENT_FORMAT",
    field: "taxRate",
    row: null,
  });
});

test("quantity grammar and range: 1.5 and 01 are INTEGER_FORMAT, 0 and 1000 are RANGE, 10000 is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, quantity: "1.5" }), {
    code: "INTEGER_FORMAT",
    field: "quantity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, quantity: "01" }), {
    code: "INTEGER_FORMAT",
    field: "quantity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, quantity: "0" }), {
    code: "RANGE",
    field: "quantity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, quantity: "1000" }), {
    code: "RANGE",
    field: "quantity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, quantity: "10000" }), {
    code: "INPUT_LIMIT",
    field: "quantity",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(
    errorOf({ price: "x", discount1: "100.01", discount2: "0", coupon: "0", taxRate: "5", quantity: "1" }),
    { code: "MONEY_FORMAT", field: "price", row: null },
  );
  assert.deepEqual(
    errorOf({ price: "100", discount1: "100.01", discount2: "x", coupon: "0", taxRate: "5", quantity: "1" }),
    { code: "RANGE", field: "discount1", row: null },
  );
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.coupon;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, price: 100 }), schema);
  assert.deepEqual(errorOf(["100"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("100"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "price", {
    enumerable: true,
    get() {
      return "100";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("a 100% first discount zeroes the price and the tax", () => {
  assert.deepEqual(run({ ...base, discount1: "100", taxRate: "5" }), {
    ok: true,
    result: {
      steps: [
        { kind: "list", priceCents: 10000 },
        { kind: "discount1", offBp: 10000, savedCents: 10000, priceCents: 0 },
        { kind: "discount2", offBp: 0, savedCents: 0, priceCents: 0 },
        { kind: "coupon", appliedCents: 0, priceCents: 0 },
        { kind: "tax", rateBp: 500, taxCents: 0, priceCents: 0 },
      ],
      unitFinalCents: 0,
      totalCents: 0,
      listTotalCents: 10000,
      totalSavedCents: 10000,
      effectiveOffPercent: "100.00",
      zhe: "0.0",
    },
  });
});

test("a coupon exactly equal to the discounted price applies in full", () => {
  const outcome = run({ ...base, coupon: "100", taxRate: "5" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result.steps[3], { kind: "coupon", appliedCents: 10000, priceCents: 0 });
  assert.equal(outcome.result.steps[4].taxCents, 0);
  assert.equal(outcome.result.effectiveOffPercent, "100.00");
  assert.equal(outcome.result.zhe, "0.0");
});

test("the largest valid price stays exact through the chain", () => {
  const outcome = run({
    price: "9999999.99",
    discount1: "0",
    discount2: "0",
    coupon: "0",
    taxRate: "0",
    quantity: "999",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.steps[0].priceCents, 999999999);
  assert.equal(outcome.result.totalCents, 998999999001);
  assert.equal(outcome.result.listTotalCents, 998999999001);
  assert.equal(outcome.result.effectiveOffPercent, "0.00");
  assert.equal(outcome.result.zhe, "10.0");
});

test("half-up at an exact .5 boundary in the tax step", () => {
  // p3 = 1050 cents, tax 5% -> 52.5 -> 53.
  const outcome = run({ ...base, price: "10.50", taxRate: "5" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result.steps[4], {
    kind: "tax",
    rateBp: 500,
    taxCents: 53,
    priceCents: 1103,
  });
});

test("property: step prices never increase before the tax step", () => {
  const inputs = [
    { price: "1299.99", discount1: "12.5", discount2: "5", coupon: "100", taxRate: "5", quantity: "2" },
    { price: "10.05", discount1: "50", discount2: "25", coupon: "1", taxRate: "0", quantity: "1" },
    { price: "0.01", discount1: "99.99", discount2: "99.99", coupon: "0", taxRate: "10", quantity: "999" },
    { price: "500", discount1: "0", discount2: "0", coupon: "9999", taxRate: "3", quantity: "1" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const prices = outcome.result.steps.slice(0, 4).map((step) => step.priceCents);
    for (let i = 1; i < prices.length; i += 1) {
      assert.ok(prices[i] <= prices[i - 1], `step ${i} increased: ${prices}`);
    }
  }
});

test("property: changing only the tax rate never changes savings or effective percent", () => {
  const shared = { price: "1299.99", discount1: "12.5", discount2: "5", coupon: "100", quantity: "2" };
  const noTax = run({ ...shared, taxRate: "0" });
  const withTax = run({ ...shared, taxRate: "5" });
  assert.equal(noTax.result.totalSavedCents, withTax.result.totalSavedCents);
  assert.equal(noTax.result.effectiveOffPercent, withTax.result.effectiveOffPercent);
  assert.equal(noTax.result.zhe, withTax.result.zhe);
});

test("property: raising a discount never raises the final unit price", () => {
  const shared = { price: "888.88", discount2: "10", coupon: "50", taxRate: "5", quantity: "1" };
  let previous = Infinity;
  for (const discount1 of ["0", "10", "25", "50", "90", "100"]) {
    const outcome = run({ ...shared, discount1 });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.unitFinalCents <= previous);
    previous = outcome.result.unitFinalCents;
  }
});

test("display formatting: money grouping, percent trimming, zhe trailing zero", () => {
  assert.equal(formatMoney(0), "0.00");
  assert.equal(formatMoney(5), "0.05");
  assert.equal(formatMoney(50), "0.50");
  assert.equal(formatMoney(113749), "1,137.49");
  assert.equal(formatMoney(999999999), "9,999,999.99");
  assert.equal(formatMoney(998999999001), "9,989,999,990.01");
  assert.equal(formatPercentBp(0), "0");
  assert.equal(formatPercentBp(2000), "20");
  assert.equal(formatPercentBp(1250), "12.5");
  assert.equal(formatPercentBp(50), "0.5");
  assert.equal(formatPercentBp(5), "0.05");
  assert.equal(formatPercentBp(10000), "100");
  assert.equal(formatZheDisplay("8.0"), "8");
  assert.equal(formatZheDisplay("10.0"), "10");
  assert.equal(formatZheDisplay("0.0"), "0");
  assert.equal(formatZheDisplay("7.2"), "7.2");
});
